sys_script_include.script:
var UserAuthUtilsDepartment = Class.create();
UserAuthUtilsDepartment.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    getUserDepartment: function() {
        // FIX: Read the parameter passed from the client instead of using gs.getUserID()
        var userId = this.getParameter('sysparm_user_id');
		gs.info('<<<userid'+userId);
        var userGR = new GlideRecord('sys_user');

        if (userGR.get(userId)) {
            // FIX: .department is a reference field. Use .getDisplayValue() to get the name string
            var deptName = userGR.department.getDisplayValue();
			gs.info('<<<deptname0'+deptName);
            if (deptName) {
                gs.info("<<< deptname : " + deptName);
                return deptName;
            }
        }
        return "No Department Assigned";
    },

    type: 'UserAuthUtilsDepartment'
});
